const dmap=new Map(dbs.map(d=>[d.id,d]));
const labels={shop:'수학B서점',library:'수학비서 DB',bank:'문제은행',mydb:'나만의 DB',source:'출처찾기&DB화',papers:'내 문제지',account:'마이페이지',notifications:'알림',search:'검색'};
const unique=x=>[...new Set(x.filter(Boolean))];
const opt=(values,current='',all='전체')=>`<option value="">${esc(all)}</option>`+values.map(v=>`<option ${String(v)===String(current)?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('');
const norm=s=>String(s||'').replace(/\s+/g,'').toLowerCase();
const schoolName=d=>d.schoolFullName||d.school;
const regionMatch=(a,b)=>a.replace(/특별자치|특별|광역|[시도]/g,'')===b.replace(/특별자치|특별|광역|[시도]/g,'');
const regions=['서울시','경기','인천','강원','충북','충남','대전','세종','전북','전남','광주','경북','경남','대구','울산','부산','제주'];
function go(route){if(location.hash===`#${route}`)render();else location.hash=route;}
function act(result,success){if(!result.ok)toast(result.error||'다시 확인해 주세요.');else if(success)toast(success);return result.ok;}
function nav(){renderNavigation({route:location.hash.slice(1).split('/')[0]||'library',notifications:store.getState().notifications.length});}
function heading(title,sub='',actions=''){return `<div class="heading-row"><div><h1>${esc(title)}</h1>${sub?`<p>${esc(sub)}</p>`:''}</div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;}
function breadcrumb(text){return `<div class="breadcrumb">수학비서 DB ${icon('chevron')} ${esc(text)}</div>`;}
function gradeName(g){return g?`${g.startsWith('중')?'중학교':'고등학교'} ${g.slice(1)}학년`:'';}
function sampleNote(){const examples=dbs.filter(d=>d.sample).length, sampleQuestions=questions.filter(q=>q.sample).length;return `<p class="sample-note">운영 화면에서 확인한 DB ${dbs.length-examples}개·문항 ${questions.length-sampleQuestions}개와 기능 확인용 예시 문항 ${sampleQuestions}개를 제공합니다. 예시 문항과 교재 DB ${examples}개는 실제 시험·상품 데이터가 아닙니다. 구독·구매·알림 설정은 이 브라우저에 저장됩니다.</p>`;}
function sideLibrary(current,grade){return librarySidebar(ctx,{section:'materials',kind:current,grade,query:libraryFilter.sideSearch});}

let disposeLibraryPicker=()=>{};
let libraryFilter={curriculum:createCurriculumState(),mode:'quick',special:'type',query:'',sideSearch:'',year:'',region:'',district:'',school:'',grade:'',semester:'',exam:'',subject:'',unit:'',min:'1',max:'9',explanation:'',sort:'year',brand:'',bookLevels:null,bookSubjects:null,bookBrands:null,bookPriceMin:'',bookPriceMax:'',bookLayout:'grid',showRange:true,hideOwned:false,refs:[],sourceDb:'',similarity:'all'};
function libraryFields(kind,grade){
 const f=libraryFilter,scoped=dbs.filter(d=>(kind==='root'||d.kind===kind)&&(!grade||d.grade===grade));
 if(kind==='book')return '';
 if(getVariant()==='b')return `<div class="filters">${f.mode==='quick'?`<div class="field wide-field"><span>단원 및 유형</span>${pickerMarkup('library',f.curriculum)}</div>`:''}<label class="field"><span>연도</span><select name="year">${opt(Array.from({length:25},(_,i)=>2026-i),f.year)}</select></label></div>`;
 return `<div class="filters">${f.mode==='quick'?`<div class="field wide-field"><span>단원 및 유형</span>${pickerMarkup('library',f.curriculum)}</div>`:''}<label class="field"><span>연도</span><select name="year">${opt(Array.from({length:25},(_,i)=>2026-i),f.year)}</select></label>${!grade?`<label class="field"><span>학년</span><select name="grade">${opt(grades,f.grade)}</select></label>`:''}<label class="field"><span>학기</span><select name="semester">${opt(['1학기','2학기'],f.semester)}</select></label><label class="field"><span>시험</span><select name="exam">${opt(['중간','기말'],f.exam)}</select></label><label class="field wide-field"><span>과목</span><select name="subject">${opt(unique(scoped.map(d=>d.subject)),f.subject)}</select></label></div>`;
}
function dbRow(d,owned=false){const rights=store.ownedDBs().find(x=>x.id===d.id);const subscribed=rights?.active;const alert=store.getState().schoolAlerts.includes(schoolName(d));return `<div class="db-row" data-db="${esc(d.id)}" tabindex="0" role="group" aria-label="${esc(d.title)}"><div class="db-range">${libraryFilter.showRange?esc(d.range||d.subject):'<span>—</span>'}</div><div><button class="db-title" data-preview="${esc(d.id)}">${esc(d.title)} ${icon('chevron')}</button><div class="db-meta"><span class="badge">${d.count}문제</span><span class="badge">평균 ${d.avg??'미확인'}</span>${d.bins?.length?`<span class="distribution">${d.bins.map((b,i)=>`<span style="--c:${['#dd8500','#00764b','#e1555a','#494952'][i]}">${b}</span>`).join('')}</span>`:''}</div><div class="db-meta"><span>${esc(d.format||'DB Pro')}</span><span>·</span><span>${esc(d.explanation||'해설 미확인')}</span>${owned?`<span class="badge ${subscribed?'blue':'red'}">${rights.mode==='permanent'?'영구 소유':'구독한 DB'}${rights.mode!=='permanent'&&!store.isActive('db')?(subscribed?' · 일부 이용 가능 · 구독 종료':' · 만료'):''}</span><span>${rights.availableCount}/${d.count}문항 이용 가능</span>`:d.rentalEligible===false?'<span class="badge orange">구독 제외</span>':''}</div></div><div class="price"><span class="muted">상점 DB 가격</span>${d.originalPrice?`<del>${money(d.originalPrice)}</del>`:''}<strong>${d.price==null?'미확인':money(d.price)}</strong><span class="sample-only">${esc(d.status)}</span></div><div class="row-actions"><button class="btn small" data-open-db="${esc(d.id)}">${owned?'DB 열기':'파일정보'}</button><button class="btn small" data-create-db-paper="${esc(d.id)}">이 DB로 문제지 만들기</button><div class="row" style="justify-content:center"><button class="icon-btn" data-preview="${esc(d.id)}" aria-label="${esc(d.school||d.title)} 미리보기">${icon('search')}</button>${d.school?`<button class="icon-btn ${alert?'on':''}" data-school-alert="${esc(schoolName(d))}" aria-label="${esc(schoolName(d))} 알림 ${alert?'해제':'설정'}" aria-pressed="${alert}">${icon('bell')}</button>`:''}</div></div></div>`;}
function dbTable(list,owned=false){if(getVariant()==='b'&&!owned)return schoolDBTable(ctx,list,{showRange:libraryFilter.showRange,curriculumLabel:libraryFilter.curriculum.curriculum==='old'?'구교육':'신교육'});return `<div class="db-list"><div class="db-head"><div>시험범위 (신교육)</div><div>제목</div><div>DB Pro</div><div>미리보기 · 정보</div></div>${list.length?list.map(d=>dbRow(d,owned)).join(''):'<div class="empty"><h3>검색 결과가 없습니다.</h3><p>지역이나 검색어를 바꿔 보세요.</p></div>'}</div>`;}
function queryDBs(kind,grade){const f=libraryFilter;const own=new Set(store.ownedDBs().map(d=>d.id));
 if(kind==='book')return filterBookOptions(dbs,f,ctx).filter(d=>(!f.hideOwned||!own.has(d.id))&&(!f.query||f.query.trim().split(/[\s,]+/).map(norm).every(w=>norm([d.title,d.publisher,d.grade,d.subject].join(' ')).includes(w)))).sort((a,b)=>compareBookCatalog(a,b,f.sort));
 const curriculumDBs=(f.mode==='quick'||f.special==='type')&&f.curriculum.selectedPaths.length?new Set(questions.filter(q=>questionMatchesCurriculum(q,f.curriculum)).map(q=>q.dbId)):null;
 return dbs.filter(d=>{
 if(curriculumDBs&&!curriculumDBs.has(d.id))return false;
 if(!f.sideSearch&&kind!=='root'&&d.kind!==kind)return false;
 if(!f.sideSearch&&grade&&d.grade!==grade)return false;
 if(f.grade&&d.grade!==f.grade)return false;
 const hay=norm([d.title,d.schoolFullName,d.region,d.district,d.publisher,d.range].join(' '));
 if((f.query&&!f.query.trim().split(/[\s,]+/).map(norm).every(w=>hay.includes(w)))||(f.sideSearch&&!f.sideSearch.trim().split(/[\s,]+/).map(norm).every(w=>hay.includes(w))))return false;
 if(f.year&&String(d.year)!==f.year||f.region&&!regionMatch(d.region,f.region)||f.district&&d.district!==f.district||f.semester&&d.semester!==f.semester||f.exam&&d.exam!==f.exam)return false;
 if(f.school&&schoolName(d)!==f.school)return false;
 if(f.subject&&d.subject!==f.subject&&d.publisher!==f.subject)return false;
 if((f.mode==='quick'||f.special==='type')&&f.unit&&!norm(d.range).includes(norm(f.unit)))return false;
 if(f.hideOwned&&own.has(d.id))return false;
 if(f.explanation==='yes'&&!/해설 있음/.test(d.explanation))return false;
 if(f.explanation==='no'&&!/해설 없음/.test(d.explanation))return false;
 if(f.mode==='special'){
  if(['type','source'].includes(f.special)&&d.avg!=null&&(d.avg<Number(f.min)||d.avg>Number(f.max)))return false;
  if(f.special==='specific'&&f.refs.length){const refs=f.refs.map(id=>qmap.get(id));if(!refs.some(q=>q?.grade===d.grade))return false;}
  if(f.special==='source'&&f.sourceDb){const base=dmap.get(f.sourceDb);if(base&&base.grade!==d.grade)return false;}
  if(f.similarity!=='all'&&f.special!=='type')return d.questionIds.some(id=>{const q=qmap.get(id);const bases=f.special==='specific'?f.refs.map(x=>qmap.get(x)):questions.filter(x=>x.dbId===f.sourceDb);return bases.some(b=>similarity(q,b)===f.similarity);});
 }
 return true;
}).sort((a,b)=>f.sort==='name'?a.title.localeCompare(b.title,'ko'):b.year-a.year);}
function renderLibrary(parts){const kind=parts[1]==='materials'?'root':parts[1]==='books'?'book':parts[1]||'root',grade=getVariant()==='b'?'':parts[2]||'';const f=libraryFilter;if(getVariant()==='b'&&parts[2]&&grades.includes(parts[2])){f.grade=parts[2];history.replaceState(null,'','#library/'+kind);}if(kind==='book')prepareBookScope(f);const list=queryDBs(kind,grade);const title=f.sideSearch?'DB 검색 결과':grade?gradeName(grade):kind==='book'?'교재 DB':kind==='school'?'내신폴더':'수학비서 DB';renderLibraryCatalog(page,ctx,{kind,grade,filter:f,list,fieldsHTML:libraryFields(kind,grade),tableHTML:dbTable(list),sampleHTML:sampleNote(),actionsHTML:''});
 if(f.sideSearch){const terms=f.sideSearch.trim().split(/[\s,]+/).map(norm),matches=questions.filter(q=>terms.every(t=>norm([q.text,q.title,q.unit,q.sourceTitle,q.grade].join(' ')).includes(t)));page.querySelector('.lc-catalog').insertAdjacentHTML('beforeend',`<section class="global-bank-matches"><div class="section-heading"><h2>문제은행 문항</h2><span>${matches.length}문항</span></div>${matches.length?`<div class="question-grid">${matches.map(q=>questionCard(q,{store,source:'bank'})).join('')}</div>`:'<p class="muted">검색 조건에 맞는 문항이 없습니다.</p>'}</section>`);bindQuestions(page,'bank');}

 const form=page.querySelector('#library-form');
 const read=()=>{
  if(page.querySelector('#library-form')!==form)return false;
  if(kind==='book')return readBookFilters(page,f,form);
  for(const e of form.elements)if(e.name&&e.type!=='checkbox'&&e.type!=='radio')f[e.name]=e.value;
  return true;
 };
 const apply=()=>{if(!read())return;const error=kind==='book'?bookPriceError(f):f.mode==='special'&&f.special!=='specific'&&Number(f.min)>Number(f.max)?'최소 난이도를 확인해 주세요.':'';if(error)return toast(error);render();};
 form.onsubmit=e=>{e.preventDefault();apply();};
 if(kind==='book')for(const e of libraryFormControls(page,form)){if(e.type==='checkbox')e.onchange=apply;else if(['bookPriceMin','bookPriceMax'].includes(e.name))e.onchange=apply;}
 form.querySelector('[name="sourceDb"]')?.querySelectorAll('option').forEach(o=>{if(o.value)o.textContent=dmap.get(o.value).title;});
 page.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{read();f.mode=b.dataset.mode;f.unit='';if(f.mode==='quick'){f.min='1';f.max='9';}render();});
 page.querySelectorAll('[data-special]').forEach(b=>b.onclick=()=>{read();f.special=b.dataset.special;render();});
 page.querySelector('#reset-filters').onclick=()=>{libraryFilter={...libraryFilter,curriculum:createCurriculumState(),query:'',year:'',region:'',district:'',school:'',grade:'',semester:'',exam:'',subject:'',unit:'',min:'1',max:'9',refs:[],sourceDb:'',similarity:'all',sideSearch:'',brand:'',bookLevels:null,bookSubjects:null,bookBrands:null,bookPriceMin:'',bookPriceMax:'',explanation:'',hideOwned:false};render();};
 page.querySelector('#side-search-form').onsubmit=e=>{e.preventDefault();searchLibrary(page.querySelector('#side-search').value);};
 page.querySelector('#clear-side')?.addEventListener('click',()=>{f.sideSearch='';render();});
 const favoriteRegion=page.querySelector('#favorite-region');if(favoriteRegion)favoriteRegion.onclick=()=>{read();if(!f.region||!f.district)return toast('지역과 시·군·구를 선택해 주세요.');act(store.saveRegionFavorite({region:f.region,district:f.district}),'관심 지역을 저장했습니다.');};
 page.querySelectorAll('[data-favorite-region]').forEach(b=>b.onclick=()=>{read();const location=store.regionFavoriteLocation(b.dataset.favoriteRegion);if(location)Object.assign(f,location);if(kind==='book'){previousScope='library/school';go('library/school');}else render();});
 page.querySelector('#plan-info')?.addEventListener('click',()=>subscribe('db'));
 page.querySelector('#db-sort').onchange=e=>{f.sort=e.target.value;render();};
 page.querySelector('#hide-owned').onchange=e=>{f.hideOwned=e.target.checked;render();};
 page.querySelector('#show-range')?.addEventListener('change',e=>{f.showRange=e.target.checked;render();});
 page.querySelector('#explanation-filter')?.addEventListener('change',e=>{f.explanation=e.target.value;render();});
 page.querySelector('#choose-reference')?.addEventListener('click',()=>chooseReferences());
 bindDBActions();bindLibraryCatalog(page,ctx,{filter:f,onChange:render,beforeChange:read,onReset:()=>page.querySelector('#reset-filters')?.click()});
 disposeLibraryPicker=bindCurriculumPicker(page,'library',{questions,state:f.curriculum,onChange:()=>{read();render();}});
}
function createDBPaper(id){const db=dmap.get(id);if(!db)return;const launch=()=>createDialog(ctx,{title:db.title+' 문제지',filters:{source:'library',dbId:id,grade:db.grade}});if(questions.some(q=>q.dbId===id))return launch();openModal({title:'문항 표본이 없는 DB입니다',body:`<p>${esc(db.title)}</p><p>이 DB는 목록 정보만 제공합니다. 선택한 DB로 검색 조건을 설정한 빈 문제지를 만들 수 있으며, 다른 DB의 문항을 대신 넣지 않습니다.</p>`,footer:'<button class="btn" data-cancel>닫기</button><button class="btn primary" data-create>문제지 만들기</button>',onMount:d=>{d.querySelector('[data-cancel]').onclick=closeModal;d.querySelector('[data-create]').onclick=launch;}});}
function searchLibrary(query){Object.assign(libraryFilter,{curriculum:createCurriculumState(),sideSearch:query.trim(),query:'',grade:'',unit:'',mode:'quick',special:'type',year:'',region:'',district:'',subject:'',semester:'',exam:'',sourceDb:'',refs:[],similarity:'all',brand:'',school:'',bookLevels:null,bookSubjects:null,bookBrands:null,bookPriceMin:'',bookPriceMax:'',hideOwned:false,explanation:'',min:'1',max:'9'});previousScope='library';go('library');}
function bindLibrarySidebar(){const form=page.querySelector('#side-search-form');if(form)form.onsubmit=e=>{e.preventDefault();searchLibrary(page.querySelector('#side-search').value);};page.querySelectorAll('[data-favorite-region]').forEach(b=>b.onclick=()=>{const location=store.regionFavoriteLocation(b.dataset.favoriteRegion);if(location)Object.assign(libraryFilter,location);libraryFilter.sideSearch='';previousScope='library/school';go('library/school');});}
function bindDBActions(root=page){root.querySelectorAll('[data-create-db-paper]').forEach(b=>b.onclick=()=>createDBPaper(b.dataset.createDbPaper));root.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>previewDB(b.dataset.preview));root.querySelectorAll('[data-open-db]').forEach(b=>b.onclick=()=>openDB(b.dataset.openDb));root.querySelectorAll('[data-db]').forEach(row=>{row.ondblclick=e=>{if(!e.target.closest('button'))openDB(row.dataset.db);};row.onkeydown=e=>{if(e.key==='Enter'&&e.target===row)openDB(row.dataset.db);};});root.querySelectorAll('[data-school-alert]').forEach(b=>b.onclick=()=>notifySchool(b.dataset.schoolAlert));root.querySelectorAll('[data-school-detail]').forEach(b=>b.onclick=()=>openSchoolDetail(b.dataset.schoolDetail));root.querySelectorAll('[data-db-cart]').forEach(input=>input.onchange=()=>{input.checked?ctx.commerce.purchase(input.dataset.dbCart,'cart'):ctx.commerce.remove(input.dataset.dbCart);});}
function notifySchool(school){
 const enabled=store.getState().schoolAlerts.includes(school);
 openModal({title:enabled?'새 시험지 알림을 해제할까요?':'새 시험지가 등록되면 알림받을까요?',body:`<p><strong>${esc(school)}</strong></p><p>${enabled?'이 학교의 새 시험지 알림을 더 이상 받지 않습니다.':'해당 학교의 새로운 시험지가 등록되면 알림을 받을까요?'}</p>`,footer:`<button class="btn" data-alert-cancel>취소</button><button class="btn primary" data-alert-confirm>${enabled?'알림 해제':'알림받기'}</button>`,onMount:modal=>{modal.querySelector('[data-alert-cancel]').onclick=closeModal;modal.querySelector('[data-alert-confirm]').onclick=()=>{if(act(store.toggleSchool(school),enabled?'새 시험지 알림을 해제했습니다.':'새 시험지가 등록되면 알려드릴게요.'))closeModal();};}});
}
function openSchoolDetail(id){go('library/detail/'+id);toast('시험지 미리보기가 보여집니다.');}
function purchaseDB(id,action='buy'){ctx.commerce.purchase(id,action);}
function chooseReferences(){let selected=new Set(libraryFilter.refs);openModal({title:'기준 문항 선택 · 최대 20개',wide:true,body:`<div class="db-question-grid">${questions.map(q=>`<label class="panel checkbox"><input type="checkbox" value="${q.id}" ${selected.has(q.id)?'checked':''}><span>${esc(q.grade)} · ${esc(q.title)}<small class="muted" style="display:block">${esc(q.sourceTitle)} ${q.number}번</small></span></label>`).join('')}</div>`,footer:'<button class="btn primary" data-save>선택 적용</button>',onMount:d=>{d.querySelectorAll('input').forEach(i=>i.onchange=()=>{if(i.checked&&selected.size>=20){i.checked=false;return toast('20문항까지 선택할 수 있습니다.');}i.checked?selected.add(i.value):selected.delete(i.value);});d.querySelector('[data-save]').onclick=()=>{libraryFilter.refs=[...selected];closeModal();render();};}});}
function subscribe(kind,after){if(store.isActive(kind)){if(after)return after();return go('account');}const isBank=kind==='bank';const name=isBank?'문제은행':'DB';openModal({title:`${name} 구독`,body:`<span class="badge blue">월 구독</span><div class="price-big">${money(isBank?39000:49000)} <small>/ 월</small></div><p>${isBank?'문제은행 구독으로 중1부터 고3까지 전체 학년의 문항을 이용하세요.':'DB 구독으로 전체 학년의 구독 대상 내신·교재 DB를 이용하세요.'}</p><ul class="plan-list">${(isBank?['중1부터 고3까지 전체 학년 이용','여러 문항 선택 · 문제지 담기','학습지·시험지·랜덤 출제']:['전체 학년의 구독 대상 내신·교재 DB 이용','필요한 문항 선택 · 나만의 DB 보관','구독 DB 이력 보관 · 재구독 시 복구']).map(s=>`<li>${icon('check')}${s}</li>`).join('')}</ul><div class="notice">기본 기기 1대 · 회원 등급에 따라 최대 4대<br>추가 기기 1대당 월 15,000원 · 총 10대까지</div><p class="small-note">해지 예약 후 이용 기간이 끝날 때까지 사용할 수 있습니다. 구독 만료 시 문항 일부가 흐려지고 출제·다운로드를 사용할 수 없습니다. 영구 구매 문항은 계속 이용할 수 있습니다.</p><label class="checkbox" style="margin-top:20px"><input id="plan-agree" type="checkbox">이용 조건을 확인했습니다.</label><p class="sample-note">이 화면은 프로토타입입니다. 실제 결제나 정기 청구는 발생하지 않습니다.</p>`,footer:'<button class="btn" data-no>닫기</button><button class="btn primary" data-plan disabled>구독 시작하기</button>',onMount:d=>{d.querySelector('[data-no]').onclick=closeModal;d.querySelector('#plan-agree').onchange=e=>d.querySelector('[data-plan]').disabled=!e.target.checked;d.querySelector('[data-plan]').onclick=()=>{if(act(store.subscribePlan(kind),`${name} 구독을 시작했습니다.`)){closeModal();after?.();}};}});}
function openDB(id){const d=dmap.get(id);if(d?.kind==='school'&&getVariant()==='b'&&!/^#(?:mydb|source)/.test(location.hash))return openSchoolDetail(id);if(!d)return;if(d.kind==='book')return openBookInfo(ctx,id,{acquireAll});const own=store.ownedDBs().find(x=>x.id===id);const active=Boolean(own?.active||store.isActive('db')&&d.rentalEligible!==false);const qs=questions.filter(q=>q.dbId===id);openModal({title:'DB 파일정보',wide:active,body:`${d.kind==='book'&&d.preview?`<img class="book-detail-cover" src="${esc(d.preview)}" alt="교재 표지">`:''}<span class="badge">${esc(d.kind==='school'?'내신 DB':'교재 DB')}</span>${own?` <span class="badge ${active?'blue':'red'}">${own.mode==='permanent'?'영구 소유':'구독한 DB'}${own.mode!=='permanent'&&!store.isActive('db')?(active?' · 일부 이용 가능 · 구독 종료':' · 만료'):''}</span>`:''}<h3 style="margin-top:14px;line-height:1.6">${esc(d.title)}</h3><dl class="details"><dt>출처</dt><dd>${esc([d.year,d.region,d.district,d.schoolFullName||d.school,d.publisher].filter(Boolean).join(' · '))}</dd><dt>학년 · 과목</dt><dd>${esc(d.grade)} · ${esc(d.subject)}</dd><dt>학기 · 시험</dt><dd>${esc(d.semester)} ${esc(d.exam)}</dd><dt>문항 정보</dt><dd>${d.count}문항 · 평균 난이도 ${d.avg??'미확인'}</dd><dt>시험범위</dt><dd>${esc(d.range)}</dd><dt>파일 형식</dt><dd>${esc(d.format||'DB Pro')} · ${esc(d.explanation)}</dd><dt>상태</dt><dd>${esc(d.status)}</dd><dt>상점 가격</dt><dd>${money(d.price)}${d.originalPrice?` <del class="muted">${money(d.originalPrice)}</del>`:''}</dd>${own?`<dt>보관 문항</dt><dd>${own.ownedCount}/${d.count}문항</dd><dt>현재 이용 가능</dt><dd>${own.availableCount}/${d.count}문항</dd><dt>영구 구매</dt><dd>${own.permanentCount}/${d.count}문항 · 나머지 ${own.remainingPurchaseCount}문항</dd>`:''}</dl>${!active?`<div class="notice">${icon('lock')}<span>${d.rentalEligible===false?'이 교재는 DB 구독에 포함되지 않습니다.':own?'DB 구독이 종료되었습니다. 재구독하면 다시 이용할 수 있습니다.':'DB를 구독해야 문항을 보고 문제지에 사용할 수 있습니다.'}</span></div>`:`<div class="section-heading"><h3>DB 문항</h3><span class="sample-only">${d.previewExample?'예시':'수집한'} ${qs.length}문항 / 원본 ${d.count}문항</span></div>${qs.length?`<div class="db-question-grid">${qs.map(q=>questionCard(q,{store})).join('')}</div>`:'<div class="empty">이 DB는 목록 정보만 수집했습니다. 실제 문항 표본은 중1 서울여중·고1 심석고에서 확인할 수 있습니다.</div>'}`}`,footer:`<button class="btn" data-preview-db>미리보기</button>${d.rentalEligible===false?'<button class="btn" data-buy-all>전체 구매하기</button>':active?`${own?.remainingPurchaseCount?'<button class="btn" data-buy-rest>나머지 영구 구매</button>':''}${!store.isActive('db')&&own?.remainingPurchaseCount?'<button class="btn primary" data-db-plan>DB 구독하기</button>':''}${!own?'<button class="btn primary" data-rest>나만의 DB에 추가</button>':'<button class="btn primary" data-done>확인</button>'}`:'<button class="btn primary" data-db-plan>DB 구독하기</button>'}`,onMount:modal=>{modal.querySelector('[data-preview-db]').onclick=()=>previewDB(id);modal.querySelector('[data-done]')?.addEventListener('click',closeModal);modal.querySelector('[data-db-plan]')?.addEventListener('click',()=>subscribe('db',()=>openDB(id)));modal.querySelector('[data-buy-all]')?.addEventListener('click',()=>acquireAll(id,'permanent'));modal.querySelector('[data-buy-rest]')?.addEventListener('click',()=>acquireAll(id,'permanent'));modal.querySelector('[data-rest]')?.addEventListener('click',()=>acquireAll(id,'rental'));bindQuestions(modal,'db');}});}
function acquireAll(id,mode){if(mode==='rental'&&!store.isActive('db'))return subscribe('db',()=>acquireAll(id,mode));const d=dmap.get(id);const own=store.ownedDBs().find(x=>x.id===id);const count=own?.remainingPurchaseCount??d.count;openModal({title:mode==='permanent'?'DB 구매하기':'나만의 DB에 추가',body:`<p><strong>${esc(d.title)}</strong></p><p style="margin-top:14px">${mode==='permanent'?`${count}문항을 영구 소유로 추가합니다.`:'이 DB를 나만의 DB에 보관합니다. 구독 중에는 별도 등록 없이 전체 학년의 구독 대상 문항을 이용할 수 있습니다.'}</p><p class="small-note" style="margin-top:14px">원본 전체 이용권을 확인하는 프로토타입입니다. 이 프로토타입에는 ${d.questionIds.length}개 문항 이미지만 들어 있습니다. 실제 결제는 발생하지 않습니다.</p>`,footer:'<button class="btn" data-no>취소</button><button class="btn primary" data-yes>추가하기</button>',onMount:m=>{m.querySelector('[data-no]').onclick=()=>openDB(id);m.querySelector('[data-yes]').onclick=()=>{if(act(store.acquireRemaining(id,mode),'나만의 DB에 추가했습니다.')){closeModal();openDB(id);}};}});}
function previewDB(id){const d=dmap.get(id);if(!d)return;const qs=questions.filter(q=>q.dbId===id);openModal({title:`${d.school||d.publisher||'DB'} 미리보기`,body:qs.length?`<div class="preview-pages">${qs.reduce((acc,q,i)=>{if(i%3===0)acc.push([]);acc.at(-1).push(q);return acc;},[]).map((arr,i)=>`<div class="preview-page"><h3>${esc(d.title)}</h3><small>${d.previewExample?'예시':'수집한'} 문항 미리보기 · ${i+1}쪽</small>${arr.map(q=>`<strong>${q.number}.</strong>${renderNumericQuestionImage(q,{locked:!store.canUseQuestion(q.id,'db'),alt:q.number+'번 문제 미리보기'})}`).join('')}</div>`).join('')}</div><p class="sample-note">${d.previewExample?'화면 기능을 확인하는 예시이며 해당 학교의 실제 시험 문항이 아닙니다.':`운영 시험지 미리보기 형식으로 구성한 표본입니다. 원본 ${d.count}문항 중 ${qs.length}문항을 수집했습니다.`}</p>`:d.preview?`<div class="preview-pages"><div class="preview-page"><h3>${esc(d.title)}</h3><img src="${esc(d.preview)}" alt="교재 표지"></div></div><p class="sample-note">교재 표지 미리보기입니다. 본문 문항은 수집하지 않았습니다.</p>`:`<div class="empty">${icon('book')}<h3>파일정보만 수집한 DB입니다.</h3><p>문항 미리보기는 중1 서울여중·고1 심석고 표본에서 확인할 수 있습니다.</p><button class="btn" id="sample-preview">중1 표본 미리보기</button></div>`,onMount:m=>m.querySelector('#sample-preview')?.addEventListener('click',()=>previewDB('school-225416'))});}
function requestQuestion(id,source='db'){const q=qmap.get(id);if(!q)return;if(store.canUseQuestion(id,source)){openModal({title:`${q.grade} · ${q.number}번 문항`,body:`<div class="question-image">${renderNumericQuestionImage(q,{locked:!store.canUseQuestion(id,source),alt:q.title})}</div><dl class="details"><dt>유형</dt><dd>${esc(q.unit)}</dd><dt>난이도</dt><dd>${q.difficulty} · ${esc(q.answerType)}</dd><dt>출처</dt><dd>${esc(q.sourceTitle)}</dd></dl>`,footer:'<button class="btn primary" data-add>문제지에 담기</button>',onMount:m=>m.querySelector('[data-add]').onclick=()=>addQuestions([id],source)});return;}if(source==='bank')return openBankQuestionAccess(ctx,q);return openQuestionSelectionAccess(ctx,[q],{source:'db'});}
function bindQuestions(root,source){root.querySelectorAll('[data-qopen]').forEach(b=>b.onclick=()=>requestQuestion(b.dataset.qopen,source));root.querySelectorAll('[data-qaction]').forEach(b=>b.onclick=()=>addQuestions([b.dataset.qaction],source));}
function addQuestions(ids,source='db',options={}){const selected=new Set(ids),ordered=questions.filter(q=>selected.has(q.id)).map(q=>q.id);if(!ordered.length)return;const destination={originLabel:source==='bank'?'수학비서 DB · 문제은행':'수학비서 DB · 자료 DB',...structuredClone(options)};if(ordered.some(id=>!store.canUseQuestion(id,source)))return openQuestionSelectionAccess(ctx,ordered,{source,onComplete:()=>addQuestions(ordered,source,destination)});return openPaperDestination(ctx,ordered,source,destination);}

let cleanupBankPicker=()=>{};
let bankFilter={curriculum:createCurriculumState(),min:'1',max:'9',answers:[],include:'',exclude:'',unit:''};let bankSelected=new Set();let lastBankGrade='';
function renderBank(parts){cleanupBankPicker();const grade=parts[1]||'중1';if(lastBankGrade!==grade){bankSelected.clear();bankFilter.curriculum.selectedPaths=[];const validUnits=new Set(questions.filter(q=>q.grade===grade).map(q=>q.tags?.[0]).filter(Boolean));if(bankFilter.unit&&!validUnits.has(bankFilter.unit))bankFilter.unit='';lastBankGrade=grade;}const f=bankFilter;const active=store.isActive('bank');let list=filterPaperQuestions(questions,{...f,grade},{dbs});if(f.unit)list=list.filter(q=>q.unit.includes(f.unit));bankSelected=new Set([...bankSelected].filter(id=>qmap.get(id)?.grade===grade));const visibleSelected=list.filter(q=>bankSelected.has(q.id)).length;page.innerHTML=`<div class="split-view">${librarySidebar(ctx,{section:'bank',kind:'root',grade,query:''})}<section class="workspace bank-workspace"><div class="breadcrumb"><a href="#library">수학비서 DB</a> ${icon('chevron')} <a href="#bank">문제은행</a> ${icon('chevron')} ${esc(grade)}</div>${heading('문제은행 · '+gradeName(grade))}${bankSubscriptionBanner(ctx)}<div class="bank-grade-chips chips">${grades.map(g=>`<a class="chip ${g===grade?'active':''}" href="#bank/${g}">${g}</a>`).join('')}</div><form id="bank-form" class="bank-filter-panel filter-panel"><h3>문항 필터</h3><div class="field"><span>단원 및 유형</span>${pickerMarkup('bank',f.curriculum)}</div><div class="field"><span>난이도</span><div class="range"><input name="min" type="number" min="1" max="9" value="${f.min}" aria-label="최소 난이도"><span>~</span><input name="max" type="number" min="1" max="9" value="${f.max}" aria-label="최대 난이도"></div></div><div class="field"><span>정답 종류</span><div class="check-list">${['객관식','주관식','증명','O/X'].map(t=>`<label class="checkbox"><input type="checkbox" name="answers" value="${t}" ${f.answers.includes(t)?'checked':''}>${t}</label>`).join('')}</div></div><label class="field"><span>텍스트 및 수식 포함</span><input name="include" placeholder="예: 소인수, 2^a" value="${esc(f.include)}"></label><label class="field"><span>텍스트 및 수식 제외</span><input name="exclude" placeholder="제외할 내용" value="${esc(f.exclude)}"></label><div class="row"><button class="btn primary" style="flex:1">검색하기</button><button class="btn" type="button" id="reset-bank">초기화</button></div></form>${!active?`<div class="notice">${icon('lock')}<span>${store.getState().subscriptions.bank.status==='expired'?'문제은행 구독이 종료되었습니다. 구매한 문항은 계속 쓸 수 있고, 나머지는 재구독 후 이용할 수 있어요.':'구매하지 않은 문항의 숫자와 수식만 흐리게 표시합니다. 한 문항씩 구매하거나 구독해 이용하세요.'}</span></div>`:''}<div class="list-toolbar"><label class="checkbox"><input type="checkbox" id="select-all-bank" ${list.length&&visibleSelected===list.length?'checked':''} ${list.length?'':'disabled'}>전체 선택 (${list.length})</label><span class="grow"></span><span class="muted">텍스트·수식과 유형으로 검색</span></div>${list.length?`<div class="question-grid">${list.map(q=>questionCard(q,{store,source:'bank',selectable:true,selected:bankSelected.has(q.id)})).join('')}</div>`:`<div class="empty"><h3>검색 결과가 없습니다.</h3></div>`}${bankSelected.size?`<div class="sticky-selection"><strong>${bankSelected.size}문항 선택</strong><button class="text-btn" style="color:white" id="clear-bank">선택 해제</button><button class="btn primary" id="add-bank">${icon('plus')}문제지에 담기</button></div>`:''}${sampleNote()}</section></div>`;cleanupBankPicker=bindCurriculumPicker(page,'bank',{questions,state:f.curriculum,onChange:()=>{f.unit='';renderBank(parts);}});const form=page.querySelector('#bank-form');form.onsubmit=e=>{e.preventDefault();for(const key of ['min','max','include','exclude'])f[key]=form.elements[key].value;f.answers=[...form.querySelectorAll('[name=answers]:checked')].map(i=>i.value);if(Number(f.min)>Number(f.max))return toast('최소 난이도를 확인해 주세요.');render();};page.querySelector('#reset-bank').onclick=()=>{bankFilter={curriculum:createCurriculumState(),min:'1',max:'9',answers:[],include:'',exclude:'',unit:''};render();};bindLibraryBanners(page,ctx);const selectAll=page.querySelector('#select-all-bank');selectAll.indeterminate=visibleSelected>0&&visibleSelected<list.length;selectAll.onchange=e=>{list.forEach(q=>e.target.checked?bankSelected.add(q.id):bankSelected.delete(q.id));render();};page.querySelectorAll('[data-qcheck]').forEach(i=>i.onchange=()=>{i.checked?bankSelected.add(i.dataset.qcheck):bankSelected.delete(i.dataset.qcheck);render();});page.querySelector('#clear-bank')?.addEventListener('click',()=>{bankSelected.clear();render();});page.querySelector('#add-bank')?.addEventListener('click',()=>addQuestions([...bankSelected],'bank',{originLabel:'문제은행 · '+grade,filters:{...bankFilter,source:'bank',grade}}));bindQuestions(page,'bank');bindLibrarySidebar();}

function similarity(q,b){if(!q||!b)return '';if(q.id===b.id||norm(q.text)===norm(b.text))return 'same';const strip=s=>norm(s).replace(/[0-9]+/g,'#');if(strip(q.text)===strip(b.text))return 'number';if(q.grade===b.grade&&q.tags.some(t=>b.tags.includes(t)))return 'similar';return '';}
function renderSearch(){page.innerHTML=`<section class="global-search">${heading('검색','내신·교재 DB와 문제은행 문항을 검색하세요.')}<form id="global-search-form"><div class="searchbox">${icon('search')}<input name="query" placeholder="학교, 과목, 문항 텍스트 또는 수식" aria-label="전체 검색어" required><button class="btn primary">검색</button></div><div class="chips"><label class="checkbox"><input name="target" type="radio" value="db" checked>수학비서 DB</label><label class="checkbox"><input name="target" type="radio" value="bank">문제은행</label></div></form></section>`;page.querySelector('form').onsubmit=e=>{e.preventDefault();const f=e.target;if(f.elements.target.value==='db'){searchLibrary(f.elements.query.value);}else{bankFilter.include=f.elements.query.value.trim();if(getVariant()==='c')setStudioSearch(bankFilter.include);go('bank/중1');}};}
function renderHome(){page.innerHTML=`<section class="workspace account-wrap">${heading('수학비서','수업에 필요한 자료를 찾아 문제지로 만드세요.')}<div class="two-cols"><div class="panel"><span class="badge blue">DB 구독</span><h2 style="margin-top:14px">수학비서 DB</h2><p>DB 구독으로 전체 학년의 내신·교재 자료를 이용하세요.</p><a class="btn primary" href="#library">DB 찾아보기 ${icon('chevron')}</a></div><div class="panel"><span class="badge blue">문제은행</span><h2 style="margin-top:14px">필요한 문항만 골라 담기</h2><p>난이도와 유형으로 찾은 문항을 내 문제지에 담으세요.</p><a class="btn primary" href="#bank/중1">문항 찾아보기 ${icon('chevron')}</a></div></div><div class="section-heading"><h2>이어서 작업하기</h2></div><div class="panel"><div class="row"><div><h3>내 문제지 ${store.getState().papers.length}개</h3><p>직접 고르거나 랜덤으로 문제지를 만들 수 있습니다.</p></div><span class="grow"></span><a class="btn" href="#papers">내문제지 열기</a></div></div>${sampleNote()}</section>`;}
